#include <iostream>
#include <string>

int main() {
    std::string anterior;
    std::string actual;
    int posicion{0};
    int repeticiones{0};
    while (std::cin >> actual) {
        ++posicion;
        if (actual == anterior) {
            ++repeticiones;
            std::cout << "Repetida: " << posicion << '\n';
        }
        anterior = actual;
    }
    std::cout << "Palabras: " << posicion
              << "\nRepeticiones: " << repeticiones << '\n';
    return 0;
}

