#include <iostream>
#include <string>

int main() {
    std::string anterior;
    std::string actual;
    bool hay_anterior{false};
    int posicion{0};
    int repeticiones{0};
    while (std::getline(std::cin, actual)) {
        ++posicion;
        if (hay_anterior && actual == anterior) {
            ++repeticiones;
            std::cout << "Repetida: " << posicion << '\n';
        }
        anterior = actual;
        hay_anterior = true;
    }
    std::cout << "Lineas: " << posicion
              << "\nRepeticiones: " << repeticiones << '\n';
    return 0;
}

